api-validate-schema.solution:
def _type_ok(kind, v):
    if kind == "bool":
        return isinstance(v, bool)
    if isinstance(v, bool):
        return False
    if kind == "int":
        return isinstance(v, int)
    if kind == "float":
        return isinstance(v, (int, float))
    if kind == "str":
        return isinstance(v, str)
    return False

TYPE_ERR = {"int": "int_type", "float": "float_type", "str": "string_type", "bool": "bool_type"}

def validate(data, schema):
    errors = []
    for name, rule in schema.items():
        loc = ["body", name]
        if name not in data:
            if rule.get("required", True):
                errors.append([loc, "missing"])
            continue
        v, kind = data[name], rule["type"]
        if not _type_ok(kind, v):
            errors.append([loc, TYPE_ERR[kind]])
            continue
        if kind in ("int", "float"):
            if "min" in rule and v < rule["min"]:
                errors.append([loc, "greater_than_equal"]); continue
            if "max" in rule and v > rule["max"]:
                errors.append([loc, "less_than_equal"]); continue
        if kind == "str":
            if "min_length" in rule and len(v) < rule["min_length"]:
                errors.append([loc, "string_too_short"]); continue
            if "max_length" in rule and len(v) > rule["max_length"]:
                errors.append([loc, "string_too_long"]); continue
    for k in data:
        if k not in schema:
            errors.append([["body", k], "extra_forbidden"])
    return errors

api-di-resolver.solution:
def resolveOrder(providers, target, overrides):
    order, done, active = [], set(), set()

    def visit(name):
        actual = overrides.get(name, name)
        if actual in done:
            return True
        if actual in active:
            return False
        active.add(actual)
        for dep in providers[actual]:
            if not visit(dep):
                return False
        active.discard(actual)
        done.add(actual)
        order.append(actual)
        return True

    return order if visit(target) else ["cycle"]

api-middleware-chain.solution:
class _Boom(Exception):
    pass

def runChain(middlewares, path):
    trace = []

    def handler():
        trace.append("handler")
        if path == "/boom":
            raise _Boom()
        return 200, {}

    def wrap(spec, inner):
        kind, _, rest = spec.partition(":")
        if kind == "trace":
            def mw():
                trace.append(rest + ">")
                st, h = inner()
                trace.append("<" + rest)
                return st, h
        elif kind == "block":
            name, _, prefix = rest.partition(":")
            def mw():
                if path.startswith(prefix):
                    trace.append(name + "!")
                    return 403, {}
                return inner()
        elif kind == "catch":
            def mw():
                try:
                    return inner()
                except _Boom:
                    trace.append(rest + " caught")
                    return 500, {}
        elif kind == "header":
            k, _, v = rest.partition(":")
            def mw():
                st, h = inner()
                h = dict(h)
                h[k] = v
                return st, h
        else:
            raise ValueError(spec)
        return mw

    app = handler
    for spec in reversed(middlewares):
        app = wrap(spec, app)
    try:
        st, h = app()
    except _Boom:
        trace.append("server_error")
        st, h = 500, {}
    return [st, h, trace]

