api-etag-check.solution:
import hashlib

def conditionalGet(body, if_none_match):
    etag = '"' + hashlib.sha256(body.encode("utf-8")).hexdigest()[:16] + '"'
    if if_none_match is not None:
        raw = if_none_match.strip()
        if raw == "*":
            return [304, etag, ""]
        for item in raw.split(","):
            tag = item.strip()
            if tag.startswith("W/"):
                tag = tag[2:]
            if tag == etag:
                return [304, etag, ""]
    return [200, etag, body]

api-route-match.solution:
def matchRoute(template, path):
    t = template.split("/")
    p = path.split("/")
    out = {}
    for i, seg in enumerate(t):
        if seg.startswith("{") and seg.endswith("}"):
            name, _, conv = seg[1:-1].partition(":")
            if conv == "path":
                if i > len(p):
                    return None
                out[name] = "/".join(p[i:])
                return out
            if i >= len(p):
                return None
            val = p[i]
            if conv == "int":
                if not val or not all("0" <= c <= "9" for c in val):
                    return None
                out[name] = int(val)
            else:
                if val == "":
                    return None
                out[name] = val
        else:
            if i >= len(p) or p[i] != seg:
                return None
    if len(p) != len(t):
        return None
    return out

