api-query-parse.solution:
from urllib.parse import unquote_plus

TRUE = {"true", "1", "yes", "on"}
FALSE = {"false", "0", "no", "off"}

def _conv(kind, v):
    if kind == "str":
        return v
    if kind == "int":
        return int(v)
    if kind == "float":
        return float(v)
    if kind == "bool":
        lv = v.lower()
        if lv in TRUE:
            return True
        if lv in FALSE:
            return False
        raise ValueError(v)
    raise ValueError(kind)

def parseQuery(query, schema):
    raw = {}
    for pair in query.split("&"):
        if not pair:
            continue
        k, _, v = pair.partition("=")
        raw.setdefault(unquote_plus(k), []).append(unquote_plus(v))
    values, errors = {}, []
    for name, kind in schema.items():
        if name not in raw:
            continue
        try:
            if kind.startswith("list["):
                inner = kind[5:-1]
                values[name] = [_conv(inner, v) for v in raw[name]]
            else:
                values[name] = _conv(kind, raw[name][-1])
        except ValueError:
            errors.append(name)
    return {"values": values, "errors": sorted(errors)}

