api-idempotency-store.solution:
class IdempotencyStore:
    def __init__(self, ttl):
        self.ttl = ttl
        self.rec = {}  # key -> [body_hash, created, response or None]

    def _live(self, key, now):
        r = self.rec.get(key)
        if r is None:
            return None
        if now - r[1] >= self.ttl:
            del self.rec[key]
            return None
        return r

    def begin(self, key, body_hash, now):
        r = self._live(key, now)
        if r is None:
            self.rec[key] = [body_hash, now, None]
            return "new"
        if r[0] != body_hash:
            return "conflict"
        if r[2] is None:
            return "in_progress"
        return "replay:" + r[2]

    def complete(self, key, response, now):
        r = self._live(key, now)
        if r is None:
            return False
        r[2] = response
        return True

    def fail(self, key, now):
        r = self._live(key, now)
        if r is None:
            return False
        del self.rec[key]
        return True

