def formBatches(arrivals, max_batch, max_wait):
    out, cur, deadline = [], [], None
    for i, t in enumerate(arrivals):
        if cur and t > deadline:
            out.append([deadline, cur])
            cur = []
        if not cur:
            deadline = t + max_wait
        cur.append(i)
        if len(cur) == max_batch:
            out.append([t, cur])
            cur = []
    if cur:
        out.append([deadline, cur])
    return out

